    // 336 MHz is within the allowable VCO range (96 to 344 MHz for STM32G4).
    // RCC_PLLCFGR_PLLSRC_HSE = 0x03 (depending on header, usually HSE is 0b11 or 0b10. In stm32g4xx.h: RCC_PLLCFGR_PLLSRC_0 | RCC_PLLCFGR_PLLSRC_1 for HSE)

