    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Busy-wait until HSE is ready */
    }

    /* 2. Configure Flash wait states (4 WS for 168 MHz in Range 1 boost mode) */
    FLASH->ACR &= ~FLASH_ACR_LATENCY;
    FLASH->ACR |= FLASH_ACR_LATENCY_4WS;

