    // Enable Power interface clock
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    // Set VOS to Range 1 (01b) in PWR_CR1
    PWR->CR1 &= ~PWR_CR1_VOS;
    PWR->CR1 |= (1U << 15); // VOS = 01b (bit 15=1, bit 14=0)

    // Wait until VOSF flag in PWR_SR2 is cleared
    while (PWR->SR2 & PWR_SR2_VOSF) {
        /* Busy-wait for voltage scaling readiness */
    }

    // Ensure Range 1 boost mode (R1MODE = 0 in PWR_CR5)
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 4. Configure PLL: Source = HSE (8 MHz), VCO = 8 MHz * 84 = 672 MHz, PLLR = 4 -> 168 MHz */
    // First, ensure PLL is disabled before modifying its configuration
    RCC->CR &= ~RCC_CR_PLLON;
    while (RCC->CR & RCC_CR_PLLRDY) {
        /* Busy-wait until PLL is fully stopped */
    }

    // Configure PLLCFGR:
    // - PLLSRC = HSE (11b)
    // - PLLM = /1 (0000b, meaning division factor 1)
    // - PLLN = *84 (84 in bits [14:8])
    // - PLLREN = enabled (bit 24 = 1)
    // - PLLR = /4 (01b, meaning division factor 4)
    // - PLLP = /2 or other (cleared/default)
    RCC->PLLCFGR = (RCC_PLLCFGR_PLLSRC_HSE) |
                   ((84U << RCC_PLLCFGR_PLLN_Pos) & RCC_PLLCFGR_PLLN_Msk) |
                   (0U << RCC_PLLCFGR_PLLM_Pos) | /* PLLM = 1 (encoded as 0000) */
                   (1U << RCC_PLLCFGR_PLLR_Pos) | /* PLLR = 4 (encoded as 01b) */
                   RCC_PLLCFGR_PLLREN;

    /* 5. Enable PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Busy-wait until PLL is ready */
    }

