    // Switch system clock source to PLL (SW = 11b)
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;

    /* 7. Wait until PLL is used as system clock (SWS == 11b) */
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Busy-wait for clock switch to take effect */
    }

